INSERT INTO RegistrationLineup (RegistrationID, AccountID, Slot, InGameNameSnapshot, PlayerCredentialID) SELECT 1, a.AccountID, 'SUBSTITUTE', 'RXE.Lux1', (SELECT c.PlayerCredentialID FROM PlayerCredential c WHERE c.AccountID = a.AccountID AND c.CredentialType = 'IN_GAME_NAME' LIMIT 1) FROM Account a WHERE a.Email = 'rxe.p1@demo.etoms' AND NOT EXISTS (SELECT 1 FROM RegistrationLineup l WHERE l.RegistrationID = 1 AND l.AccountID = a.AccountID);
